?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz Background Remover</title><meta name="description" content="Remove image backgrounds quickly in your browser with SmartToolz."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,500,0,0&display=swap" rel="stylesheet"><style>:root{--p:#635bff;--p2:#8b7cff;--ink:#151824;--muted:#777f90;--line:#e5e8ef;--bg:#f6f7fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif}.material-symbols-rounded{font-size:20px;vertical-align:middle}.app{width:min(1120px,calc(100% - 28px));margin:auto;padding:22px 0 44px}.head{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:14px}.ey{font-size:10px;font-weight:900;color:#5b53d8;letter-spacing:.5px}.head h1{margin:7px 0 5px;font-size:clamp(30px,4.5vw,50px);line-height:1;letter-spacing:-2.4px}.head p{margin:0;font-size:11px;color:var(--muted)}.guide{padding:10px 13px;border:1px solid #dedbff;border-radius:10px;background:#fff;color:#554bd5;font-size:9px;font-weight:900}.tool{overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:0 18px 55px rgba(30,35,75,.08)}.top{height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 14px;border-bottom:1px solid var(--line)}.state{display:flex;align-items:center;gap:8px;font-size:9px;font-weight:850}.dot{width:7px;height:7px;border-radius:50%;background:#16a34a;box-shadow:0 0 0 4px #dcfce7}.actions{display:flex;gap:6px}.ghost{border:1px solid var(--line);background:#fff;border-radius:8px;padding:7px 10px;font-size:8px;font-weight:850;color:#515a6c}.stage{min-height:600px;display:grid;place-items:center;padding:22px;background:repeating-conic-gradient(#edf0f4 0 25%,#fafbfd 0 50%) 50%/28px 28px}.drop{width:min(620px,100%);padding:46px 24px;text-align:center;background:rgba(255,255,255,.95);border:2px dashed #c6cbd6;border-radius:24px}.drop.drag{border-color:var(--p);box-shadow:0 0 0 6px rgba(99,91,255,.08)}.icon{width:60px;height:60px;margin:0 auto 12px;display:grid;place-items:center;border-radius:17px;background:#efedff;color:#5a51d6}.drop h2{font-size:22px;margin:0 0 7px;letter-spacing:-.5px}.drop p{max-width:460px;margin:0 auto 17px;color:var(--muted);font-size:10px;line-height:1.7}.choose{display:inline-flex;align-items:center;gap:7px;padding:13px 20px;border:0;border-radius:12px;background:linear-gradient(135deg,var(--p),var(--p2));color:#fff;font-size:11px;font-weight:900}.sub{margin-top:10px;font-size:8px;color:#9aa1ad}.canvas{display:none;width:min(900px,100%);height:min(520px,70vh);position:relative;align-items:center;justify-content:center}.canvas canvas{display:block;max-width:100%;max-height:100%;box-shadow:0 20px 60px rgba(15,20,40,.18);border-radius:14px}.busy{display:none;position:absolute;left:18px;right:18px;bottom:18px;max-width:560px;margin:auto;padding:13px 14px;border-radius:14px;background:#151823;color:#fff}.busyrow{display:flex;justify-content:space-between;font-size:8px;font-weight:900}.bar{height:5px;margin-top:8px;border-radius:99px;overflow:hidden;background:#303440}.bar i{display:block;width:0;height:100%;background:linear-gradient(90deg,var(--p),var(--p2))}.footerbar{display:none;gap:8px;padding:11px;border-top:1px solid var(--line);background:#fff}.footerbar button{flex:1;border:1px solid var(--line);border-radius:9px;padding:10px;background:#fff;color:#50596b;font-size:9px;font-weight:900}.footerbar .primary{background:#171925;color:#fff;border-color:#171925}.result{display:none;padding:15px;border-top:1px solid var(--line)}.resulthead{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}.resulthead b{font-size:12px}.resulthead span{font-size:8px;color:var(--muted)}.compare{position:relative;min-height:300px;overflow:hidden;border-radius:14px;background:#ddd}.compare img{display:block;width:100%;height:100%;max-height:500px;object-fit:contain}.compare .after{position:absolute;inset:0;width:50%;overflow:hidden;border-right:2px solid #fff}.compare .after img{width:100%;height:100%;object-fit:contain}.compare input{position:absolute;inset:0;width:100%;opacity:0;cursor:ew-resize}.tip{text-align:center;margin-top:8px;color:#9299a6;font-size:8px}@media(max-width:650px){.app{width:calc(100% - 14px);padding-top:12px}.head{display:block}.guide{display:inline-flex;margin-top:10px}.stage{min-height:450px;padding:10px}.drop{padding:34px 14px}.canvas{height:360px}.footerbar{flex-direction:column}.footerbar button{width:100%}}</style></head><body><?php require_once __DIR__.'/../header.php'; ?><main class="app"><header class="head"><div><div class="ey">SMARTTOOLZ • BACKGROUND REMOVER</div><h1>Remove the background. <span style="color:var(--p)">Keep the subject.</span></h1><p>One clear action. Fast browser processing. Download when it’s done.</p></div><a class="guide" href="/knowledge-base/image-background-remover/article/">How to use this tool</a></header><section class="tool"><div class="top"><div class="state"><i class="dot"></i><span id="status">Ready to remove</span></div><div class="actions"><button class="ghost" id="new">New image</button></div></div><div class="stage" id="stage"><div class="drop" id="drop"><div class="icon"><span class="material-symbols-rounded">content_cut</span></div><h2>Remove background</h2><p>Choose an image and SmartToolz will automatically isolate the subject.</p><label class="choose"><span class="material-symbols-rounded">upload_file</span> Choose image<input id="picker" hidden type="file" accept="image/png,image/jpeg,image/webp"></label><div class="sub">PNG • JPG • WebP</div></div><div class="canvas" id="canvas"><canvas id="out"></canvas><div class="busy" id="busy"><div class="busyrow"><span>Removing background…</span><span id="pct">0%</span></div><div class="bar"><i id="fill"></i></div></div></div></div><div class="footerbar" id="footer"><button id="again">↺ Try another</button><button id="download" class="primary">↓ Download PNG</button></div><div class="result" id="result"><div class="resulthead"><b>Before / After</b><span>Drag the slider</span></div><div class="compare"><img id="before" alt="Original"><div class="after"><img id="after" alt="Background removed"></div><input id="slider" type="range" min="0" max="100" value="50"></div><div class="tip">Background removed — compare the original and result.</div></div></section></main><script type="module">import{removeBackground}from'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';const $=id=>document.getElementById(id);const picker=$('picker'),drop=$('drop'),canvasWrap=$('canvas'),canvas=$('out'),ctx=canvas.getContext('2d'),busy=$('busy'),fill=$('fill'),pct=$('pct'),status=$('status'),footer=$('footer'),result=$('result'),before=$('before'),after=$('after');let outUrl='',sourceUrl='';function reset(){picker.value='';drop.style.display='block';canvasWrap.style.display='none';busy.style.display='none';footer.style.display='none';result.style.display='none';status.textContent='Ready to remove';if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl);outUrl='';sourceUrl=''}async function img(src){return new Promise((r,j)=>{const i=new Image();i.onload=()=>r(i);i.onerror=j;i.src=src})}async function run(file){if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type))return;drop.style.display='none';canvasWrap.style.display='flex';busy.style.display='block';footer.style.display='none';result.style.display='none';sourceUrl=URL.createObjectURL(file);before.src=sourceUrl;try{const blob=await removeBackground(file,{model:'small',output:{format:'image/png',quality:1},progress:(k,c,t)=>{const p=t?Math.max(5,Math.min(96,Math.round(c/t*90)+5)):5;fill.style.width=p+'%';pct.textContent=p+'%';status.textContent='Removing background'}});outUrl=URL.createObjectURL(blob);const im=await img(outUrl),w=im.naturalWidth,h=im.naturalHeight;canvas.width=w;canvas.height=h;ctx.clearRect(0,0,w,h);ctx.drawImage(im,0,0,w,h);after.src=outUrl;fill.style.width='100%';pct.textContent='100%';busy.style.display='none';footer.style.display='flex';result.style.display='block';status.textContent='Background removed'}catch(e){console.error(e);busy.style.display='none';status.textContent='Could not process image'}}picker.onchange=e=>{const f=e.target.files?.[0];picker.value='';run(f)};drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');run(e.dataTransfer.files?.[0])});$('new').onclick=reset;$('again').onclick=reset;$('download').onclick=()=>{if(!outUrl)return;const a=document.createElement('a');a.href=outUrl;a.download='smarttoolz-background-removed.png';a.click()};$('slider').oninput=e=>{$('after').parentElement.style.width=e.target.value+'%'};window.addEventListener('beforeunload',()=>{if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl)});</script></body></html>